const b=$json.body??$json,p=b.payload??b,k=p.key??{};
const id=k.id??p.id??p.message?.id??p._data?.id;
const messageId=typeof id==='string'?id:(id?._serialized??id?.id??'');
const chat=k.remoteJid??p.from??p.chatId??p._data?.from??'';
const chatId=typeof chat==='string'?chat:'';
const rawFromMe=k.fromMe??p.fromMe??p._data?.id?.fromMe??false;
const fromMe=rawFromMe===true||rawFromMe==='true';
const eventType=String(b.event??'message'),isGroup=chatId.endsWith('@g.us');
const text=p.body??p.text??p.message?.conversation??p._data?.body??'';
const valid=typeof messageId==='string'&&messageId.length>0&&/^[0-9]+@(c\.us|s\.whatsapp\.net|lid|g\.us)$/.test(chatId)&&['message','message.any'].includes(eventType);
return [{json:{valid,external_message_id:messageId,event_type:eventType,chat_id:chatId,phone:chatId.replace(/@.+$/,''),message_text:typeof text==='string'?text:'',from_me:fromMe,is_group:isGroup,raw:b}}];

const job = $('Claim AI Job').first().json;
const ctx = $json ?? {};

const history = ctx.history ?? [];
const lead = ctx.lead_state ?? {};
const knowledge = ctx.knowledge ?? [];

const agentInput = [
  `MODE: INBOUND_SALES`,
  `CHAT_ID: ${job.chat_id}`,
  `CURRENT CUSTOMER MESSAGE:\n${job.message_text || ''}`,
  `LEAD STATE:\n${JSON.stringify(lead)}`,
  `RECENT CONVERSATION HISTORY:\n${JSON.stringify(history)}`,
  `OFFICIAL KNOWLEDGE SNAPSHOT:\n${JSON.stringify(knowledge)}`,
  `Use the connected tools when you need to re-check official products, promotions, or FAQ.`
].join('\n\n');

return [{
  json: {
    job_id: job.job_id,
    inbound_event_id: job.inbound_event_id,
    chat_id: job.chat_id,
    attempt_count: job.attempt_count ?? 1,
    agent_input: agentInput
  }
}];

options.systemMessage:
Kamu adalah AI Sales & Customer Service Bantu Beres yang bertugas melayani calon customer melalui WhatsApp.

TUJUAN:
- pahami kebutuhan customer sebelum menawarkan;
- pilih produk resmi yang paling relevan;
- jelaskan manfaat secara natural dan singkat;
- bantu customer menuju demo/checkout jika datanya tersedia;
- tangani keberatan dengan tenang;
- gunakan CTA yang jelas tetapi tidak memaksa;
- siapkan maksimal 3 follow-up kontekstual bila customer belum mengambil keputusan;
- berhenti follow-up jika customer membalas, meminta manusia, WON, LOST, atau DO_NOT_CONTACT.

ATURAN KERAS:
- hanya gunakan fakta dari context dan tools resmi;
- jangan mengarang harga, promo, fitur, link, kebijakan, atau status pembayaran;
- jangan mengaku pembayaran berhasil tanpa bukti;
- jangan spam;
- jangan mengaku sebagai manusia;
- jika customer meminta admin/manusia atau kasus sensitif, set needs_human=true;
- output wajib sesuai Structured Output Parser.

GAYA:
Bahasa Indonesia WhatsApp yang hangat, singkat, natural, tidak seperti robot.
Contoh CTA natural: "Kalau cocok, Kak, mau saya bantu lihat demo atau langkah belinya?"

FOLLOW-UP:
Bila relevan, buat followup_plan maksimal 3 item. Setiap item berisi sequence_no, after_minutes, message.
Gunakan after_minutes yang wajar, minimal 60 menit. Hindari mengulang kalimat yang sama.

