const meta = $('Prepare Agent Input').first().json;
const decision = $json.output ?? $json;
if(!decision||typeof decision!=='object'||Array.isArray(decision)||typeof decision.should_reply!=='boolean'||typeof decision.needs_human!=='boolean'||typeof decision.stage!=='string'||typeof decision.reply!=='string'||decision.reply.length>4000)throw new Error('Invalid structured decision');
return [{json:{
  ...meta,
  decision,
  reply: decision.reply ?? '',
  model_used: $env.GEMINI_PRIMARY_MODEL,
  slot_used: 1
}}];

