const job = $('Claim AI Job').first().json;
const raw = $json ?? {};
const message =
  raw.error?.message ??
  raw.message ??
  raw.description ??
  JSON.stringify(raw).slice(0, 2000);

const attempt = Number(job.attempt_count || 1);
const delays = [5, 15, 45, 120, 300];
const delay_seconds = delays[Math.min(Math.max(attempt - 1, 0), delays.length - 1)];
return [{json:{
  job_id: job.job_id,
  attempt_count: attempt,
  should_retry: attempt < 5,
  delay_seconds,
  error_message: String(message || 'All AI providers failed')
}}];
